export const MIGRATIONS: readonly EmbeddedMigration[] = [
  { id: "0001_core", sql: "-- ============================================================\n-- JESS MOVE — core schema (specification §20)\n--\n-- Every tenant-scoped table carries tenant_id and is covered by\n-- row-level security. The Workforce API role is granted on\n-- workforce_reports only, and explicitly NOT on sessions — §16.3\n-- makes individual visibility absent rather than permission-gated.\n-- ============================================================\n\nBEGIN;\n\nCREATE EXTENSION IF NOT EXISTS \"pgcrypto\";\n\n-- ─────────── enums ───────────\n\nCREATE TYPE age_mode          AS ENUM ('explorer','teen','momentum','balance','independence','vitality');\nCREATE TYPE delivery_tier     AS ENUM ('T1','T2','T3','T4');\nCREATE TYPE movement_variant  AS ENUM ('standing','seated','chair_supported','bed_recliner','adaptive_single_limb');\nCREATE TYPE publish_state     AS ENUM ('draft','in_review','published','retired');\nCREATE TYPE snap_outcome      AS ENUM ('completed','partial','abandoned','dismissed','snoozed','expired','unsafe_stop','flagged_faked');\nCREATE TYPE safety_verdict    AS ENUM ('allow','substitute','block');\nCREATE TYPE tenant_type       AS ENUM ('consumer','employer','school','care','clinical','partner');\nCREATE TYPE wallet_bucket     AS ENUM ('promotional','subscription','purchased');\n\n-- ─────────── tenancy ───────────\n\nCREATE TABLE tenants (\n  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  type              tenant_type NOT NULL,\n  name              text NOT NULL,\n  region            text NOT NULL DEFAULT 'UK',\n  -- §16.3. The floor is 8. A tenant may raise it, never lower it.\n  k_anon_threshold  integer NOT NULL DEFAULT 8 CHECK (k_anon_threshold >= 8),\n  created_at        timestamptz NOT NULL DEFAULT now(),\n  updated_at        timestamptz NOT NULL DEFAULT now(),\n  deleted_at        timestamptz\n);\n\n-- ─────────── identity ───────────\n\nCREATE TABLE users (\n  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  tenant_id          uuid NOT NULL REFERENCES tenants(id),\n  email_hash         bytea,\n  email_enc          bytea,\n  phone_enc          bytea,\n  age_mode           age_mode NOT NULL,\n  tier               delivery_tier NOT NULL DEFAULT 'T2',\n  dob_verified_at    timestamptz,\n  is_minor           boolean NOT NULL DEFAULT false,\n  guardian_user_id   uuid REFERENCES users(id),\n  locale             text NOT NULL DEFAULT 'en-GB',\n  timezone           text NOT NULL DEFAULT 'Europe/London',\n  nudges_enabled     boolean NOT NULL DEFAULT true,\n  last_active_at     timestamptz,\n  created_at         timestamptz NOT NULL DEFAULT now(),\n  updated_at         timestamptz NOT NULL DEFAULT now(),\n  deleted_at         timestamptz,\n\n  -- §6.1 — a child is a linked minor profile, never standalone.\n  CONSTRAINT minor_requires_guardian\n    CHECK (NOT is_minor OR guardian_user_id IS NOT NULL),\n\n  -- A minor may only sit in a minor mode.\n  CONSTRAINT minor_mode_consistent\n    CHECK (is_minor = (age_mode IN ('explorer','teen')))\n);\n\nCREATE UNIQUE INDEX users_email_hash_key ON users (email_hash) WHERE email_hash IS NOT NULL;\nCREATE INDEX users_tenant_idx    ON users (tenant_id) WHERE deleted_at IS NULL;\nCREATE INDEX users_guardian_idx  ON users (guardian_user_id);\n\nCREATE TABLE capability_profiles (\n  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id             uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,\n  baseline_variant    movement_variant NOT NULL DEFAULT 'seated',\n  adaptive_flags      text[] NOT NULL DEFAULT '{}',\n  contraindications   text[] NOT NULL DEFAULT '{}',\n  volatility          text NOT NULL DEFAULT 'static',\n  instruction_ceiling smallint NOT NULL DEFAULT 3,\n  clinician_locked    boolean NOT NULL DEFAULT false,\n  confirmed_by        text NOT NULL DEFAULT 'self',\n  confirmed_at        timestamptz NOT NULL DEFAULT now(),\n  updated_at          timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX capability_contraindications_idx ON capability_profiles USING gin (contraindications);\n\n-- ─────────── library ───────────\n\nCREATE TABLE movements (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  slug           text NOT NULL UNIQUE,\n  title          text NOT NULL,\n  category       text NOT NULL,\n  state          publish_state NOT NULL DEFAULT 'draft',\n  falls_risk     boolean NOT NULL DEFAULT false,\n  anchor_required boolean NOT NULL DEFAULT false,\n  min_age        smallint NOT NULL DEFAULT 10,\n  physio_reviewer_id text,\n  review_date    date,\n  evidence_note  text,\n  created_at     timestamptz NOT NULL DEFAULT now(),\n  updated_at     timestamptz NOT NULL DEFAULT now(),\n\n  -- §11 publishing gate: a reviewer and date are required to leave draft.\n  CONSTRAINT published_requires_review\n    CHECK (state <> 'published' OR (physio_reviewer_id IS NOT NULL AND review_date IS NOT NULL))\n);\n\nCREATE TABLE movement_variants (\n  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  movement_id           uuid NOT NULL REFERENCES movements(id) ON DELETE CASCADE,\n  variant               movement_variant NOT NULL,\n  duration_seconds      integer NOT NULL,\n  contraindication_tags text[] NOT NULL DEFAULT '{}',\n  equivalence_multiplier numeric(4,2) NOT NULL DEFAULT 1.00,\n  instruction_text      text NOT NULL,\n  easy_read_text        text,\n  audio_script          text,\n  bsl_asset_id          text,\n  screening_passed      boolean NOT NULL DEFAULT false,\n\n  UNIQUE (movement_id, variant),\n\n  -- Law 1: a Snap is 90–300 seconds. Anything else is not a Snap.\n  CONSTRAINT snap_duration_bounds\n    CHECK (duration_seconds BETWEEN 90 AND 300)\n);\n\nCREATE INDEX movement_variant_contra_idx ON movement_variants USING gin (contraindication_tags);\n\n-- Cue sets: one per variant per age mode. The gate needs all five modes.\nCREATE TABLE movement_cue_sets (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  variant_id  uuid NOT NULL REFERENCES movement_variants(id) ON DELETE CASCADE,\n  age_mode    age_mode NOT NULL,\n  instructions text[] NOT NULL,\n  safety_note text,\n  UNIQUE (variant_id, age_mode),\n  CONSTRAINT instructions_non_empty CHECK (cardinality(instructions) > 0)\n);\n\n-- ─────────── context and prescription ───────────\n\nCREATE TABLE context_decisions (\n  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id           uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  evaluated_at      timestamptz NOT NULL DEFAULT now(),\n  verdict           text NOT NULL,\n  confidence        numeric(4,3) NOT NULL,\n  environment_class text NOT NULL,\n  privacy_class     text NOT NULL,\n  blocks            text[] NOT NULL DEFAULT '{}',\n  basis             text[] NOT NULL,\n  ttl_seconds       integer NOT NULL DEFAULT 900,\n\n  -- §9.2 — a decision must rest on at least one consented signal class.\n  -- There is no fixed-timer fallback.\n  CONSTRAINT basis_non_empty CHECK (cardinality(basis) > 0)\n);\n\nCREATE INDEX context_user_time_idx ON context_decisions (user_id, evaluated_at DESC);\n\nCREATE TABLE prescriptions (\n  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  tenant_id            uuid NOT NULL REFERENCES tenants(id),\n  user_id              uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  movement_id          uuid NOT NULL REFERENCES movements(id),\n  variant              movement_variant NOT NULL,\n  -- Law 2: a Snap cannot exist without a context decision.\n  context_decision_id  uuid NOT NULL REFERENCES context_decisions(id),\n  age_mode             age_mode NOT NULL,\n  tier                 delivery_tier NOT NULL,\n  duration_target_s    integer NOT NULL CHECK (duration_target_s BETWEEN 90 AND 300),\n  expected_rpe         smallint CHECK (expected_rpe BETWEEN 1 AND 10),\n  scheduled_for        timestamptz NOT NULL,\n  expires_at           timestamptz NOT NULL,\n  delivered_at         timestamptz,\n  status               text NOT NULL DEFAULT 'pending',\n  rationale_token      text,\n  model_version        text,\n  created_at           timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX rx_user_time_idx ON prescriptions (user_id, scheduled_for DESC);\nCREATE INDEX rx_expiry_idx    ON prescriptions (status, expires_at);\n\n-- §9.2 SAFE — WORM. Never updated. This is the legal defence artefact.\nCREATE TABLE safety_decisions (\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  prescription_id uuid NOT NULL REFERENCES prescriptions(id),\n  rule_id         text NOT NULL,\n  verdict         safety_verdict NOT NULL,\n  reason_code     text,\n  substituted_from uuid REFERENCES movements(id),\n  evaluated_at    timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX safety_rx_idx ON safety_decisions (prescription_id);\n\nCREATE TABLE sessions (\n  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  tenant_id           uuid NOT NULL REFERENCES tenants(id),\n  user_id             uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  prescription_id     uuid REFERENCES prescriptions(id),\n  movement_id         uuid NOT NULL REFERENCES movements(id),\n  variant             movement_variant NOT NULL,\n  started_at          timestamptz NOT NULL,\n  ended_at            timestamptz,\n  duration_s          integer,\n  rpe_reported        smallint CHECK (rpe_reported BETWEEN 1 AND 10),\n  completion_pct      numeric(5,2),\n  abandon_second      integer,\n  outcome             snap_outcome NOT NULL,\n  verification_method text,\n  proxy               boolean NOT NULL DEFAULT false,\n  proxy_by_user_id    uuid REFERENCES users(id),\n  integrity_confidence numeric(4,3) NOT NULL DEFAULT 1.0,\n  effort_score        integer,\n  offline             boolean NOT NULL DEFAULT false,\n  created_at          timestamptz NOT NULL DEFAULT now(),\n\n  CONSTRAINT proxy_has_actor CHECK (NOT proxy OR proxy_by_user_id IS NOT NULL)\n);\n\nCREATE INDEX sessions_user_time_idx ON sessions (user_id, started_at DESC);\nCREATE INDEX sessions_tenant_idx    ON sessions (tenant_id, started_at DESC);\n\nCREATE TABLE nudges (\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id         uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  prescription_id uuid REFERENCES prescriptions(id),\n  channel         text NOT NULL,\n  sent_at         timestamptz NOT NULL DEFAULT now(),\n  opened_at       timestamptz,\n  dismissed_at    timestamptz,\n  converted       boolean NOT NULL DEFAULT false,\n  -- Law 2 — a mistimed nudge is a defect against CTX, not user behaviour.\n  misfire         boolean NOT NULL DEFAULT false,\n  bandit_arm      jsonb\n);\n\nCREATE INDEX nudges_user_time_idx ON nudges (user_id, sent_at DESC);\nCREATE INDEX nudges_misfire_idx   ON nudges (misfire, sent_at DESC) WHERE misfire;\n\n-- ─────────── gamification ───────────\n\nCREATE TABLE chains (\n  user_id             uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,\n  current_days        integer NOT NULL DEFAULT 0,\n  longest_days        integer NOT NULL DEFAULT 0,\n  last_active_date    date,\n  grace_tokens        smallint NOT NULL DEFAULT 2 CHECK (grace_tokens BETWEEN 0 AND 2),\n  flare_mode_until    date,\n  hold_until          date,\n  hold_kind           text,\n  updated_at          timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE sparks_ledger (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  delta         integer NOT NULL,\n  reason        text NOT NULL,\n  session_id    uuid REFERENCES sessions(id),\n  balance_after integer NOT NULL,\n  created_at    timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX sparks_user_time_idx ON sparks_ledger (user_id, created_at DESC);\n\n-- ─────────── ACU wallet (§25.2, §16) ───────────\n\nCREATE TABLE acu_wallets (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  subject_type  text NOT NULL,\n  subject_id    uuid NOT NULL,\n  auto_topup    jsonb,\n  daily_limit   integer,\n  monthly_limit integer,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  updated_at    timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (subject_type, subject_id)\n);\n\nCREATE TABLE acu_grants (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  wallet_id   uuid NOT NULL REFERENCES acu_wallets(id) ON DELETE CASCADE,\n  bucket      wallet_bucket NOT NULL,\n  amount      integer NOT NULL CHECK (amount > 0),\n  remaining   integer NOT NULL CHECK (remaining >= 0),\n  granted_at  timestamptz NOT NULL DEFAULT now(),\n  expires_at  timestamptz NOT NULL,\n  source_ref  text,\n\n  CONSTRAINT remaining_within_amount CHECK (remaining <= amount)\n);\n\nCREATE INDEX acu_grants_spend_idx ON acu_grants (wallet_id, bucket, expires_at)\n  WHERE remaining > 0;\n\nCREATE TABLE acu_transactions (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  wallet_id      uuid NOT NULL REFERENCES acu_wallets(id) ON DELETE CASCADE,\n  delta_acu      integer NOT NULL,\n  reason         text NOT NULL,\n  agent_code     text,\n  model          text,\n  provider_cost_gbp numeric(10,6),\n  customer_charge_gbp numeric(10,6),\n  balance_after  integer NOT NULL,\n  created_at     timestamptz NOT NULL DEFAULT now(),\n\n  -- The 4x cost-protection rule, enforced in the ledger rather than\n  -- only in application code. A debit must clear four times its\n  -- direct provider cost.\n  CONSTRAINT cost_protection_4x CHECK (\n    delta_acu >= 0\n    OR provider_cost_gbp IS NULL\n    OR provider_cost_gbp = 0\n    OR customer_charge_gbp >= provider_cost_gbp * 4\n  )\n);\n\nCREATE INDEX acu_tx_wallet_time_idx ON acu_transactions (wallet_id, created_at DESC);\n\n-- ─────────── workforce reporting ───────────\n\nCREATE TABLE workforce_reports (\n  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  tenant_id         uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,\n  period            daterange NOT NULL,\n  metrics           jsonb NOT NULL,\n  suppressed_cells  jsonb NOT NULL DEFAULT '[]',\n  contributing_users integer NOT NULL,\n  generated_at      timestamptz NOT NULL DEFAULT now(),\n\n  -- §16.3 — a report may not be persisted below the k-anonymity floor.\n  CONSTRAINT k_anonymity_floor CHECK (contributing_users >= 8)\n);\n\nCREATE INDEX workforce_tenant_idx ON workforce_reports (tenant_id, generated_at DESC);\n\n-- ─────────── governance ───────────\n\nCREATE TABLE consents (\n  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id    uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  purpose    text NOT NULL,\n  basis      text NOT NULL,\n  granted    boolean NOT NULL,\n  version    text NOT NULL,\n  granted_at timestamptz,\n  revoked_at timestamptz\n);\n\nCREATE INDEX consents_user_idx ON consents (user_id, purpose);\n\nCREATE TABLE audit_log (\n  id         bigserial PRIMARY KEY,\n  actor_id   uuid,\n  actor_type text NOT NULL,\n  action     text NOT NULL,\n  resource   text NOT NULL,\n  before     jsonb,\n  after      jsonb,\n  ip         inet,\n  ts         timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX audit_ts_idx ON audit_log (ts DESC);\n\nCREATE TABLE agent_actions (\n  id             bigserial PRIMARY KEY,\n  agent_code     text NOT NULL,\n  user_id        uuid REFERENCES users(id) ON DELETE SET NULL,\n  -- §22.3 — model calls are logged with input hashes, never inputs.\n  inputs_hash    bytea NOT NULL,\n  output_summary text,\n  model          text,\n  provider       text,\n  tokens_in      integer,\n  tokens_out     integer,\n  cost_acu       numeric(10,4),\n  latency_ms     integer,\n  policy_verdict text,\n  trace_id       uuid,\n  ts             timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX agent_actions_ts_idx    ON agent_actions (ts DESC);\nCREATE INDEX agent_actions_agent_idx ON agent_actions (agent_code, ts DESC);\n\n-- ─────────── row-level security ───────────\n\nALTER TABLE users               ENABLE ROW LEVEL SECURITY;\nALTER TABLE prescriptions       ENABLE ROW LEVEL SECURITY;\nALTER TABLE sessions            ENABLE ROW LEVEL SECURITY;\nALTER TABLE workforce_reports   ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY tenant_isolation_users ON users\n  USING (tenant_id = current_setting('jessmove.tenant_id', true)::uuid);\nCREATE POLICY tenant_isolation_rx ON prescriptions\n  USING (tenant_id = current_setting('jessmove.tenant_id', true)::uuid);\nCREATE POLICY tenant_isolation_sessions ON sessions\n  USING (tenant_id = current_setting('jessmove.tenant_id', true)::uuid);\nCREATE POLICY tenant_isolation_reports ON workforce_reports\n  USING (tenant_id = current_setting('jessmove.tenant_id', true)::uuid);\n\n-- §16.3 — the workforce role. Granted on aggregates only.\n-- The absence of a grant on `sessions` is the control: individual\n-- visibility does not exist rather than being permission-gated.\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'jessmove_workforce') THEN\n    CREATE ROLE jessmove_workforce NOLOGIN;\n  END IF;\nEND $$;\n\nGRANT SELECT ON workforce_reports TO jessmove_workforce;\nREVOKE ALL ON sessions, prescriptions, users, nudges, sparks_ledger FROM jessmove_workforce;\n\nCOMMIT;\n" },
  { id: "0002_identity", sql: "-- ============================================================\n-- 0002 — Identity: registered users.\n--\n-- The service refuses a minor without a guardian and a kind that\n-- contradicts the age; this schema refuses the same writes at the\n-- storage layer, so a bug in any code path produces a rejected\n-- INSERT rather than a corrupt user.\n-- ============================================================\n\nCREATE TABLE IF NOT EXISTS app_users (\n  user_id       text PRIMARY KEY,\n  email         text NOT NULL UNIQUE,\n  password_hash text NOT NULL,\n  kind          text NOT NULL,\n  age           integer NOT NULL,\n  guardian_id   text,\n  display_name  text NOT NULL,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n\n  -- The platform serves ages 10 to 100; 120 leaves verification headroom.\n  CONSTRAINT app_users_age_range CHECK (age BETWEEN 10 AND 120),\n\n  -- Self-service registration produces exactly two kinds. Elevated kinds\n  -- are granted by an administrator through their own audited path, which\n  -- inserts with a different role — this table simply cannot hold them\n  -- from the signup flow's INSERT.\n  CONSTRAINT app_users_kind CHECK (kind IN (\n    'adult','minor','guardian','household_owner','organisation_admin',\n    'organisation_member','professional','growth_partner',\n    'support_agent','platform_staff'\n  )),\n\n  -- The two rules no code path may route around:\n  -- an under-18 is a minor, and a minor has a guardian link.\n  CONSTRAINT app_users_minor_is_minor CHECK (age >= 18 OR kind = 'minor'),\n  CONSTRAINT app_users_minor_has_guardian CHECK (kind <> 'minor' OR guardian_id IS NOT NULL),\n\n  -- Emails are stored lowercase; the unique index is only meaningful if\n  -- the column cannot quietly hold a cased duplicate.\n  CONSTRAINT app_users_email_lower CHECK (email = lower(email)),\n\n  -- Nobody is their own guardian.\n  CONSTRAINT app_users_not_own_guardian CHECK (guardian_id IS NULL OR guardian_id <> user_id)\n);\n\nCREATE INDEX IF NOT EXISTS app_users_guardian_idx ON app_users (guardian_id);\n" },
  { id: "0003_push", sql: "-- ============================================================\n-- 0003 — Push subscriptions.\n--\n-- One row per device that agreed to be woken. The endpoint is the\n-- push service URL the browser issued; p256dh/auth are the\n-- subscription's own encryption keys, and every payload is encrypted\n-- to them (RFC 8291) so the push service relays bytes it cannot read.\n-- Deleted on unsubscribe and on a 404/410 from the push service.\n-- ============================================================\n\nCREATE TABLE IF NOT EXISTS push_subscriptions (\n  endpoint   text PRIMARY KEY,\n  user_id    text,\n  p256dh     text NOT NULL,\n  auth       text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n\n  CONSTRAINT push_endpoint_https CHECK (endpoint LIKE 'https://%')\n);\n\nCREATE INDEX IF NOT EXISTS push_subscriptions_user_idx ON push_subscriptions (user_id);\n" },
  { id: "0004_state", sql: "-- ============================================================\n-- 0004 — Durable runtime state.\n--\n-- Three things that must survive a serverless instance being\n-- recycled:\n--\n--   app_wallets      — each ACU wallet as a write-through snapshot.\n--                      The spend rules live in the service and are\n--                      unit-tested; this row is what makes a granted\n--                      balance outlive the process that granted it.\n--   processed_events — the Stripe webhook's duplicate-event memory.\n--                      A replayed event finds its id here and grants\n--                      nothing twice, whichever instance receives it.\n--   guardian_confirmed — the minor-activation flag the guardian\n--                      confirmation link sets.\n-- ============================================================\n\nCREATE TABLE IF NOT EXISTS app_wallets (\n  id           text PRIMARY KEY,\n  subject_type text NOT NULL CHECK (subject_type IN ('user', 'family', 'organisation')),\n  subject_id   text NOT NULL,\n  data         jsonb NOT NULL,\n  updated_at   timestamptz NOT NULL DEFAULT now(),\n\n  CONSTRAINT app_wallets_one_per_subject UNIQUE (subject_type, subject_id)\n);\n\nCREATE TABLE IF NOT EXISTS processed_events (\n  event_id    text PRIMARY KEY,\n  kind        text,\n  received_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE app_users ADD COLUMN IF NOT EXISTS guardian_confirmed boolean NOT NULL DEFAULT false;\n" },
  { id: "0005_profile_media", sql: "-- ============================================================\n-- 0005 — Durable profile media references.\n--\n-- The pixels live in object storage (Vercel Blob); these columns are\n-- the account's pointers to them, so an avatar survives instance\n-- recycling like everything else identity-shaped. Under 18 the\n-- service refuses photographic media entirely, so for a minor these\n-- stay NULL — there is no consent switch that changes that.\n-- ============================================================\n\nALTER TABLE app_users ADD COLUMN IF NOT EXISTS avatar_url text;\nALTER TABLE app_users ADD COLUMN IF NOT EXISTS cover_url text;\n" },
  { id: "0006_mail_log", sql: "-- Outbound mail, durably.\n--\n-- The mail log started in process memory, which on serverless means every\n-- instance keeps a private diary and /mail/status is an instance lottery.\n-- Delivery diagnostics have to survive both restarts and fan-out, so the\n-- log lives here. The `detail` column carries the server's final reply on\n-- success and the exact failure reason otherwise — it is the column that\n-- answers \"did the reset email actually go out, and if not, why\".\n\nCREATE TABLE IF NOT EXISTS mail_log (\n  id         bigserial PRIMARY KEY,\n  event      text        NOT NULL,\n  recipient  text        NOT NULL,\n  subject    text        NOT NULL,\n  status     text        NOT NULL CHECK (status IN ('sent', 'sandbox', 'failed')),\n  detail     text        NOT NULL DEFAULT '',\n  at         timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS mail_log_at_idx ON mail_log (at DESC);\nCREATE INDEX IF NOT EXISTS mail_log_status_idx ON mail_log (status);\n" },
  { id: "0007_challenges", sql: "-- Team challenges, made joinable.\n--\n-- The scoring rules already existed and are deliberate: capability is\n-- absent from the score, no individual is ranked, and one strong member\n-- cannot carry a team (the contribution ceiling). What was missing was\n-- somewhere to put a challenge, a way to join one, and a record of who\n-- turned up. That is all this schema is.\n--\n-- A join code rather than an invite system: a family or a small team\n-- shares six characters and everyone is in. No directory of people, no\n-- searching for strangers, nothing public.\n\nCREATE TABLE IF NOT EXISTS challenges (\n  id          text PRIMARY KEY,\n  template    text        NOT NULL,\n  name        text        NOT NULL,\n  owner_id    text        NOT NULL,\n  join_code   text        NOT NULL UNIQUE,\n  starts_on   date        NOT NULL DEFAULT current_date,\n  ends_on     date        NOT NULL,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  CONSTRAINT challenges_run_forwards CHECK (ends_on >= starts_on)\n);\n\nCREATE TABLE IF NOT EXISTS challenge_members (\n  challenge_id text        NOT NULL REFERENCES challenges (id) ON DELETE CASCADE,\n  user_id      text        NOT NULL,\n  display_name text        NOT NULL,\n  joined_at    timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (challenge_id, user_id)\n);\n\n-- One row per act. Days active is derived from distinct dates, so a\n-- person who moves five times in one day counts as one day — the\n-- consistency term rewards showing up often, never volume.\nCREATE TABLE IF NOT EXISTS challenge_activity (\n  id           bigserial PRIMARY KEY,\n  challenge_id text        NOT NULL REFERENCES challenges (id) ON DELETE CASCADE,\n  user_id      text        NOT NULL,\n  kind         text        NOT NULL CHECK (kind IN ('moved', 'support')),\n  on_day       date        NOT NULL DEFAULT current_date,\n  at           timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS challenge_activity_lookup\n  ON challenge_activity (challenge_id, user_id, on_day);\n\nCREATE INDEX IF NOT EXISTS challenge_members_by_user\n  ON challenge_members (user_id);\n" },
  { id: "0008_activity", sql: "-- What a member actually did.\n--\n-- Every chart the platform promises — the day's timeline, the fourteen-day\n-- completion curve, the movement mix, the readings that make up Body\n-- Balance — needs a history, and until now nothing was written down. A\n-- Snap was issued and the platform immediately forgot it existed.\n--\n-- One narrow table rather than one per feature: the questions asked of it\n-- are all \"what happened, when, of what kind\", and a single log keeps a\n-- day's story in one ordering.\n\nCREATE TABLE IF NOT EXISTS member_activity (\n  id        bigserial PRIMARY KEY,\n  user_id   text        NOT NULL,\n  -- snap_offered: the engine issued one. snap_completed: they did it.\n  -- snap_held: the engine deliberately stayed silent, which is a success\n  -- and is recorded as one. food_checked: a meal went through FoodLens.\n  kind      text        NOT NULL CHECK (\n    kind IN ('snap_offered', 'snap_completed', 'snap_held', 'food_checked', 'body_read')\n  ),\n  -- Movement category for a Snap (mobility, strength, balance…), null\n  -- for anything that is not a movement.\n  category  text,\n  -- Seconds of movement where the act had a duration.\n  seconds   integer     NOT NULL DEFAULT 0 CHECK (seconds >= 0 AND seconds <= 7200),\n  on_day    date        NOT NULL DEFAULT current_date,\n  at        timestamptz NOT NULL DEFAULT now(),\n  -- The reason a prompt was held, so \"held\" is explainable rather than\n  -- merely counted.\n  detail    text        NOT NULL DEFAULT ''\n);\n\nCREATE INDEX IF NOT EXISTS member_activity_by_user_day\n  ON member_activity (user_id, on_day DESC);\n\nCREATE INDEX IF NOT EXISTS member_activity_by_user_kind\n  ON member_activity (user_id, kind, on_day DESC);\n" },
  { id: "0009_activity_value", sql: "-- A number attached to an act.\n--\n-- Some acts carry a measurement the member gave us — a weight for a body\n-- read, an energy estimate for a meal. Storing it here is what lets the\n-- trajectory and the meal-against-your-own-fortnight charts exist at all,\n-- and keeps them derived from the member's own history rather than a\n-- population average.\nALTER TABLE member_activity ADD COLUMN IF NOT EXISTS value numeric;\n" },
  { id: "0010_groups", sql: "-- Households and organisations.\n--\n-- One shape, two reporting rules, and the difference is the whole point:\n--\n--   household     — a family sees each other by name. That is what makes\n--                   a grandparent-and-grandchild streak possible.\n--   organisation  — an employer sees aggregates above a k-anonymity floor\n--                   and nothing else. There is no individual view to\n--                   permission-gate; the query never produces one.\n--\n-- A join code rather than an invite directory: six characters passed\n-- across a kitchen or a team meeting, no searching for people, nothing\n-- public.\n\nCREATE TABLE IF NOT EXISTS groups (\n  id         text PRIMARY KEY,\n  kind       text        NOT NULL CHECK (kind IN ('household', 'organisation')),\n  name       text        NOT NULL,\n  owner_id   text        NOT NULL,\n  join_code  text        NOT NULL UNIQUE,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS group_members (\n  group_id     text        NOT NULL REFERENCES groups (id) ON DELETE CASCADE,\n  user_id      text        NOT NULL,\n  display_name text        NOT NULL,\n  -- Only ever used to slice an organisation report, never to identify.\n  department   text,\n  joined_at    timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (group_id, user_id)\n);\n\nCREATE INDEX IF NOT EXISTS group_members_by_user ON group_members (user_id);\n" },
  { id: "0011_member_state", sql: "-- Where the app remembers what you were doing.\n--\n-- A member fills in their height, scans a trolley of products, gets an\n-- analysis back, then locks the phone — and everything is gone. That is\n-- not a small annoyance; it is the reason people stop opening an app.\n--\n-- One row per key per person, holding a small JSON document. Deliberately\n-- not a table per feature: the operations are all \"save this, give it\n-- back\", and a single shape keeps that honest and easy to audit.\n--\n-- Nothing sensitive belongs here. The autosave policy in the engine names\n-- the fields that may never be saved without an explicit act — consent,\n-- date of birth, clinical flags — and the service refuses those keys.\n\nCREATE TABLE IF NOT EXISTS member_state (\n  user_id    text        NOT NULL,\n  key        text        NOT NULL,\n  value      jsonb       NOT NULL,\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (user_id, key)\n);\n\nCREATE INDEX IF NOT EXISTS member_state_by_user ON member_state (user_id);\n" },
  { id: "0012_media_objects", sql: "-- ============================================================\n-- 0012 — Profile media that survives the instance it was uploaded to.\n--\n-- 0005 added the pointers; the pixels were expected to live in object\n-- storage. With no Blob store connected the storage service fell back to\n-- a Map inside one serverless instance: the upload returned 201 with a\n-- URL, and the very next request — served by a different instance —\n-- answered 404. To the member the picture uploads, never appears, and is\n-- gone on reload.\n--\n-- A database the platform already requires is a better floor than a\n-- service it might not have. Blob is still preferred when its token is\n-- present; this is what happens when it is not.\n--\n-- An avatar is capped at 5 MB and a cover at 10 MB by the upload rules,\n-- and both are stripped of metadata before they arrive here.\n-- ============================================================\n\nCREATE TABLE IF NOT EXISTS media_objects (\n  key           text PRIMARY KEY,\n  content_type  text NOT NULL,\n  bytes         bytea NOT NULL,\n  byte_size     integer NOT NULL,\n  created_at    timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS media_objects_created_idx ON media_objects (created_at DESC);\n" },
  { id: "0013_food_log", sql: "-- ============================================================\n-- 0013 — The food ledger.\n--\n-- Every scan and every analysed photograph, kept, so that FoodLens stops\n-- being a thing you use once and starts being a record of what a person\n-- actually eats. Totals across a week, a month or a year are the whole\n-- point: one meal tells you nothing, three hundred tell you where the\n-- salt is coming from.\n--\n-- Three years, then it goes. Long enough to see a year-on-year change,\n-- short enough that nobody is holding a decade of somebody's diet. A\n-- member can clear the lot at any time, and deleting the account takes it\n-- with them.\n--\n-- Nothing clinical is stored here — this is what a label said and what a\n-- photograph suggested, nothing more.\n-- ============================================================\n\nCREATE TABLE IF NOT EXISTS food_log (\n  id            text PRIMARY KEY,\n  user_id       text NOT NULL,\n  at            timestamptz NOT NULL DEFAULT now(),\n  kind          text NOT NULL CHECK (kind IN ('barcode', 'photo', 'declared', 'basket')),\n  name          text NOT NULL,\n  barcode       text,\n  grams         numeric,\n  kcal          numeric,\n  fat_g         numeric,\n  saturates_g   numeric,\n  sugars_g      numeric,\n  salt_g        numeric,\n  -- Where the figures came from: a label outranks a photograph, and the\n  -- summary says so rather than averaging the two as if they were equal.\n  basis         text NOT NULL DEFAULT 'estimate'\n                CHECK (basis IN ('label', 'calculated', 'estimate')),\n  detail        jsonb NOT NULL DEFAULT '{}'::jsonb\n);\n\nCREATE INDEX IF NOT EXISTS food_log_user_at_idx ON food_log (user_id, at DESC);\n" },
  { id: "0014_event_claim", sql: "-- ============================================================\n-- 0014 — Claim a webhook event before acting on it, not after.\n--\n-- The duplicate check was read-then-write: ask whether the event had been\n-- seen, process it, then record it. Stripe retries, and can deliver the\n-- same event to two instances at once — both read \"not seen\", both grant\n-- the plan's allowance, and both then insert with ON CONFLICT DO NOTHING.\n-- One payment, two grants. On a launch day with real cards that is money\n-- leaving the business for as long as nobody notices.\n--\n-- The unique key on event_id is already the lock; it was simply being\n-- taken too late. Claiming first makes the race impossible.\n--\n-- The reason it was written the other way round is real, though: recording\n-- only after success means a crash mid-event lets Stripe retry it. So the\n-- claim carries a state. A claim that succeeded is a duplicate forever. A\n-- claim still marked processing after fifteen minutes is a crashed attempt,\n-- and the retry is allowed to take it over.\n-- ============================================================\n\nALTER TABLE processed_events\n  ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'done'\n    CHECK (status IN ('processing', 'done'));\n\nALTER TABLE processed_events\n  ADD COLUMN IF NOT EXISTS claimed_at timestamptz NOT NULL DEFAULT now();\n\n-- Anything already recorded came from the old code, which only ever wrote\n-- a row after the work was finished. Those are done.\nUPDATE processed_events SET status = 'done' WHERE status IS NULL;\n\nCREATE INDEX IF NOT EXISTS processed_events_stuck_idx\n  ON processed_events (status, claimed_at)\n  WHERE status = 'processing';\n" },
  { id: "0015_member_conditions", sql: "-- ============================================================\n-- 0015 — What somebody lives with.\n--\n-- A person with exocrine pancreatic insufficiency reading \"your fat is\n-- high\" is being told the opposite of what their clinical team told them.\n-- A person with chronic kidney disease being nudged towards more protein\n-- is being harmed. Until the platform knows, it reads every number the\n-- same way for everybody, and for these people it reads them wrong.\n--\n-- This is the most sensitive row in the database, and it is treated that\n-- way:\n--\n--   * It is only ever written because somebody chose it themselves. There\n--     is no inference, no guess from a shopping basket, no \"people who\n--     scan this usually have that\".\n--   * One row per member, holding a list of catalogue identifiers and\n--     nothing else. No free text, no severity, no dates, no medication,\n--     no test results — none of which this platform has any business\n--     holding, and all of which would turn a preference into a record.\n--   * It never leaves the member. Household and organisation reporting\n--     reads aggregates; this table is not in any of them, at any group\n--     size, because a condition in a household of two is a name.\n--   * Deleting it is one action, and deleting the account takes it.\n--\n-- The identifiers are validated in code against the published catalogue\n-- rather than by a CHECK here, so that adding a condition is a code\n-- change reviewed as one, not a migration that quietly widens what can\n-- be stored.\n-- ============================================================\n\nCREATE TABLE IF NOT EXISTS member_conditions (\n  user_id     text PRIMARY KEY\n              REFERENCES app_users (user_id) ON DELETE CASCADE,\n  -- Catalogue identifiers, e.g. [\"pancreatic_insufficiency\",\"coeliac\"].\n  conditions  jsonb NOT NULL DEFAULT '[]'::jsonb,\n  updated_at  timestamptz NOT NULL DEFAULT now()\n);\n\n-- ------------------------------------------------------------\n-- And while we are here: the ledger outliving the account.\n--\n-- Deleting an account removed the account and left three years of what\n-- that person ate sitting in food_log, because nothing ever swept it.\n-- The fix is structural rather than a line of code somebody has to\n-- remember to call: the database itself now takes the diet with the\n-- account, so no future deletion path can forget.\n--\n-- Rows belonging to no account are removed first — they are already\n-- orphans, and an ALTER that finds one would fail the migration and\n-- take the deployment down with it.\n-- ------------------------------------------------------------\n\nDELETE FROM food_log\n WHERE user_id NOT IN (SELECT user_id FROM app_users);\n\nALTER TABLE food_log\n  DROP CONSTRAINT IF EXISTS food_log_user_fk;\n\nALTER TABLE food_log\n  ADD CONSTRAINT food_log_user_fk\n  FOREIGN KEY (user_id) REFERENCES app_users (user_id) ON DELETE CASCADE;\n" },
  { id: "0016_growth_engine", sql: "-- ============================================================\n-- 0016 — The AI Growth Engine.\n--\n-- Two tables, and the split between them is the point.\n--\n-- `growth_results` is what a partner published and what it did. Four\n-- observed numbers — reached, clicked, signed up, paid — and nothing that\n-- anybody estimated. It exists because four of the ten tools measure\n-- rather than write, and a measuring tool with nothing to measure has to\n-- either refuse or invent. This table is what lets it refuse honestly:\n-- \"eight of the fifteen results this needs\" is a true sentence, and\n-- \"post on Tuesdays\" from a model that has never seen this partner's\n-- history is not.\n--\n-- `growth_outputs` is what the engine drafted. Kept so a partner can come\n-- back to a draft, and so a claim that reached the public can be traced to\n-- the run that produced it — which matters the day an advertising\n-- regulator asks. Editable text is not stored back over the original: the\n-- draft is what we generated, and what the partner published is theirs.\n--\n-- Both cascade with the account. A partner who leaves takes their campaign\n-- history with them.\n-- ============================================================\n\nCREATE TABLE IF NOT EXISTS growth_results (\n  id           text PRIMARY KEY,\n  partner_id   text NOT NULL REFERENCES app_users (user_id) ON DELETE CASCADE,\n  tool_id      text,\n  platform     text,\n  campaign     text,\n  subject      text,\n  posted_at    timestamptz NOT NULL,\n\n  -- Observed, never modelled. A negative count is a bug upstream, not data.\n  reach        integer NOT NULL DEFAULT 0 CHECK (reach   >= 0),\n  clicks       integer NOT NULL DEFAULT 0 CHECK (clicks  >= 0),\n  signups      integer NOT NULL DEFAULT 0 CHECK (signups >= 0),\n  paid         integer NOT NULL DEFAULT 0 CHECK (paid    >= 0),\n\n  -- The funnel only narrows. More clicks than people reached means the\n  -- numbers came from two different places and the rates would be\n  -- nonsense, so the database refuses the row rather than reporting a\n  -- 400% click rate to somebody making decisions on it.\n  CONSTRAINT growth_results_funnel CHECK (\n    clicks <= reach AND signups <= clicks AND paid <= signups\n  ),\n\n  created_at   timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS growth_results_partner_idx\n  ON growth_results (partner_id, posted_at DESC);\n\nCREATE TABLE IF NOT EXISTS growth_outputs (\n  id           text PRIMARY KEY,\n  partner_id   text NOT NULL REFERENCES app_users (user_id) ON DELETE CASCADE,\n  tool_id      text NOT NULL,\n  platform     text,\n  brief        text NOT NULL,\n  -- The generated draft, as JSON, because a landing page and a hashtag\n  -- list are not the same shape and flattening both to a string would\n  -- lose the structure the partner needs.\n  output       jsonb NOT NULL DEFAULT '{}'::jsonb,\n  -- Whether it passed the copy check, and what it failed on. A refused\n  -- draft is kept: knowing the engine tried to say something and was\n  -- stopped is more useful than a gap in the record.\n  passed       boolean NOT NULL DEFAULT true,\n  problems     jsonb NOT NULL DEFAULT '[]'::jsonb,\n  acu_spent    integer NOT NULL DEFAULT 0 CHECK (acu_spent >= 0),\n  created_at   timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS growth_outputs_partner_idx\n  ON growth_outputs (partner_id, created_at DESC);\n" },
  { id: "0017_falls_checks", sql: "-- ============================================================\n-- 0017 — Strength and balance checks.\n--\n-- Three functional measures, recorded by the member, kept so that the\n-- twelve-week re-check has something to compare against. Falls and\n-- fractures cost the NHS around two billion pounds a year, and the\n-- documented failure is not that nobody knows what works — it is that\n-- community programmes are hard to stay with and stop when the block\n-- ends. A record that persists is most of what a programme is.\n--\n-- What is deliberately absent is a risk score. A real falls assessment\n-- includes medication review, lying and standing blood pressure, vision,\n-- feet and the home; this table can see none of that. Storing a \"risk\"\n-- column would invite somebody to read a reassuring number and skip the\n-- assessment they were offered, and that is the one output here that\n-- could contribute to a fall.\n--\n-- `fallen_last_year` is the strongest single predictor of the next fall\n-- and is stored because the platform must keep saying so, not because it\n-- is scored. Special-category data: it cascades with the account and\n-- never appears in a household or organisation view.\n-- ============================================================\n\nCREATE TABLE IF NOT EXISTS falls_checks (\n  id                 text PRIMARY KEY,\n  user_id            text NOT NULL REFERENCES app_users (user_id) ON DELETE CASCADE,\n  taken_at           timestamptz NOT NULL DEFAULT now(),\n\n  -- Each measure is optional: somebody may manage the chair stand and not\n  -- feel safe attempting single-leg balance, and that is a legitimate\n  -- record rather than an incomplete one.\n  chair_stand_reps   integer CHECK (chair_stand_reps  IS NULL OR chair_stand_reps  BETWEEN 0 AND 60),\n  balance_seconds    numeric CHECK (balance_seconds   IS NULL OR balance_seconds   BETWEEN 0 AND 40),\n  up_and_go_seconds  numeric CHECK (up_and_go_seconds IS NULL OR up_and_go_seconds BETWEEN 0 AND 300),\n\n  fallen_last_year   boolean NOT NULL DEFAULT false,\n  afraid_of_falling  boolean NOT NULL DEFAULT false,\n\n  -- The level the platform derived at the time. Kept so a later change to\n  -- the thresholds cannot silently rewrite somebody's history.\n  level              text NOT NULL,\n\n  created_at         timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS falls_checks_user_idx\n  ON falls_checks (user_id, taken_at DESC);\n" },
];

export const CONSTRAINT_SUITE: string = "-- ============================================================\n-- Schema invariant tests.\n--\n-- Each block asserts that the database REJECTS a write that would\n-- violate a rule from the specification. A constraint that does not\n-- fire here is not enforcement — it is documentation.\n--\n-- Run:  psql -d jessmove -v ON_ERROR_STOP=1 -f db/test/constraints.sql\n-- ============================================================\n\n\\set QUIET on\n\\pset tuples_only on\n\nCREATE OR REPLACE FUNCTION pg_temp.must_reject(stmt text, label text)\nRETURNS text LANGUAGE plpgsql AS $$\nBEGIN\n  BEGIN\n    EXECUTE stmt;\n  EXCEPTION WHEN others THEN\n    RETURN 'ok   — ' || label;\n  END;\n  RAISE EXCEPTION 'NOT REJECTED — %', label;\nEND $$;\n\nBEGIN;\n\nINSERT INTO tenants (id, type, name)\nVALUES ('11111111-1111-1111-1111-111111111111', 'employer', 'Test Co');\n\nINSERT INTO users (id, tenant_id, age_mode, is_minor)\nVALUES ('22222222-2222-2222-2222-222222222222',\n        '11111111-1111-1111-1111-111111111111', 'momentum', false);\n\nINSERT INTO movements (id, slug, title, category, state)\nVALUES ('33333333-3333-3333-3333-333333333333', 'test-mv', 'Test', 'mobility', 'draft');\n\n-- ── §6.1 a minor may not exist without a guardian ──\nSELECT pg_temp.must_reject($$\n  INSERT INTO users (tenant_id, age_mode, is_minor)\n  VALUES ('11111111-1111-1111-1111-111111111111', 'explorer', true)\n$$, 'a minor cannot be created without a guardian');\n\n-- ── a minor may not sit in an adult mode ──\nSELECT pg_temp.must_reject($$\n  INSERT INTO users (tenant_id, age_mode, is_minor, guardian_user_id)\n  VALUES ('11111111-1111-1111-1111-111111111111', 'momentum', true,\n          '22222222-2222-2222-2222-222222222222')\n$$, 'a minor cannot be placed in an adult mode');\n\n-- ── Law 1: a Snap is 90–300 seconds ──\nSELECT pg_temp.must_reject($$\n  INSERT INTO movement_variants (movement_id, variant, duration_seconds, instruction_text)\n  VALUES ('33333333-3333-3333-3333-333333333333', 'seated', 45, 'too short')\n$$, 'a 45-second variant is not a Snap');\n\nSELECT pg_temp.must_reject($$\n  INSERT INTO movement_variants (movement_id, variant, duration_seconds, instruction_text)\n  VALUES ('33333333-3333-3333-3333-333333333333', 'standing', 600, 'too long')\n$$, 'a 600-second variant is not a Snap');\n\n-- ── §11: a movement cannot be published without a named reviewer ──\nSELECT pg_temp.must_reject($$\n  INSERT INTO movements (slug, title, category, state)\n  VALUES ('unreviewed', 'Unreviewed', 'balance', 'published')\n$$, 'publishing without a physio reviewer is rejected');\n\n-- ── §9.2: a context decision must rest on a real signal ──\nSELECT pg_temp.must_reject($$\n  INSERT INTO context_decisions\n    (user_id, verdict, confidence, environment_class, privacy_class, basis)\n  VALUES ('22222222-2222-2222-2222-222222222222', 'movable', 0.9, 'desk', 'alone', '{}')\n$$, 'a context decision with no basis is rejected');\n\n-- ── Law 2: a prescription requires a context decision (NOT NULL FK) ──\nSELECT pg_temp.must_reject($$\n  INSERT INTO prescriptions\n    (tenant_id, user_id, movement_id, variant, age_mode, tier,\n     duration_target_s, scheduled_for, expires_at)\n  VALUES ('11111111-1111-1111-1111-111111111111',\n          '22222222-2222-2222-2222-222222222222',\n          '33333333-3333-3333-3333-333333333333',\n          'seated', 'momentum', 'T2', 150, now(), now() + interval '20 min')\n$$, 'a Snap cannot be prescribed without a context decision');\n\n-- ── §16.3: a cohort report below k=8 cannot be persisted ──\nSELECT pg_temp.must_reject($$\n  INSERT INTO workforce_reports (tenant_id, period, metrics, contributing_users)\n  VALUES ('11111111-1111-1111-1111-111111111111',\n          daterange('2026-01-01','2026-02-01'), '{}'::jsonb, 7)\n$$, 'a report with 7 contributing users is rejected');\n\n-- ── §16.3: the k-anonymity floor cannot be lowered by a tenant ──\nSELECT pg_temp.must_reject($$\n  INSERT INTO tenants (type, name, k_anon_threshold)\n  VALUES ('employer', 'Lower The Floor Ltd', 4)\n$$, 'a tenant cannot set a k-anonymity threshold below 8');\n\n-- ── the 4x cost-protection rule, enforced in the ledger ──\nINSERT INTO acu_wallets (id, subject_type, subject_id)\nVALUES ('44444444-4444-4444-4444-444444444444', 'user',\n        '22222222-2222-2222-2222-222222222222');\n\nSELECT pg_temp.must_reject($$\n  INSERT INTO acu_transactions\n    (wallet_id, delta_acu, reason, provider_cost_gbp, customer_charge_gbp, balance_after)\n  VALUES ('44444444-4444-4444-4444-444444444444', -20, 'meal_analysis', 0.15, 0.30, 100)\n$$, 'a debit charging only 2x provider cost is rejected');\n\n-- ── grace tokens cannot exceed the monthly allowance ──\nSELECT pg_temp.must_reject($$\n  INSERT INTO chains (user_id, grace_tokens)\n  VALUES ('22222222-2222-2222-2222-222222222222', 5)\n$$, 'more than 2 grace tokens per month is rejected');\n\n-- ── a proxy session must name the person acting ──\nSELECT pg_temp.must_reject($$\n  INSERT INTO sessions\n    (tenant_id, user_id, movement_id, variant, started_at, outcome, proxy)\n  VALUES ('11111111-1111-1111-1111-111111111111',\n          '22222222-2222-2222-2222-222222222222',\n          '33333333-3333-3333-3333-333333333333',\n          'seated', now(), 'completed', true)\n$$, 'a proxy session must record who acted');\n\n-- ── an ACU grant cannot have more remaining than was granted ──\nSELECT pg_temp.must_reject($$\n  INSERT INTO acu_grants (wallet_id, bucket, amount, remaining, expires_at)\n  VALUES ('44444444-4444-4444-4444-444444444444', 'subscription', 200, 500,\n          now() + interval '90 days')\n$$, 'a grant cannot have more remaining than granted');\n\n-- ── the happy path still works ──\nINSERT INTO movement_variants (movement_id, variant, duration_seconds, instruction_text)\nVALUES ('33333333-3333-3333-3333-333333333333', 'seated', 150, 'Sit tall, open the chest.');\n\nINSERT INTO context_decisions\n  (id, user_id, verdict, confidence, environment_class, privacy_class, basis)\nVALUES ('55555555-5555-5555-5555-555555555555',\n        '22222222-2222-2222-2222-222222222222', 'movable', 0.86, 'desk', 'semi_public',\n        ARRAY['calendar','motion']);\n\nINSERT INTO prescriptions\n  (tenant_id, user_id, movement_id, variant, context_decision_id, age_mode, tier,\n   duration_target_s, scheduled_for, expires_at)\nVALUES ('11111111-1111-1111-1111-111111111111',\n        '22222222-2222-2222-2222-222222222222',\n        '33333333-3333-3333-3333-333333333333',\n        'seated', '55555555-5555-5555-5555-555555555555', 'momentum', 'T2',\n        150, now(), now() + interval '25 min');\n\nINSERT INTO workforce_reports (tenant_id, period, metrics, contributing_users)\nVALUES ('11111111-1111-1111-1111-111111111111',\n        daterange('2026-01-01','2026-02-01'), '{\"participation\":0.41}'::jsonb, 12);\n\nSELECT 'ok   — a valid Snap, context decision and k=12 report all insert';\n\n\n-- ------------------------------------------------------------\n-- 0002 — identity\n-- ------------------------------------------------------------\n\nSELECT pg_temp.must_reject(\n  $q$ INSERT INTO app_users (user_id,email,password_hash,kind,age,guardian_id,display_name)\n      VALUES ('t_1','kid@example.com','x','adult',15,NULL,'Kid') $q$,\n  'an under-18 cannot hold an adult account');\n\nSELECT pg_temp.must_reject(\n  $q$ INSERT INTO app_users (user_id,email,password_hash,kind,age,guardian_id,display_name)\n      VALUES ('t_2','kid2@example.com','x','minor',15,NULL,'Kid') $q$,\n  'a minor without a guardian link is rejected');\n\nSELECT pg_temp.must_reject(\n  $q$ INSERT INTO app_users (user_id,email,password_hash,kind,age,guardian_id,display_name)\n      VALUES ('t_3','MiXeD@Example.com','x','adult',30,NULL,'Cased') $q$,\n  'a non-lowercase email is rejected');\n\nSELECT pg_temp.must_reject(\n  $q$ INSERT INTO app_users (user_id,email,password_hash,kind,age,guardian_id,display_name)\n      VALUES ('t_4','self@example.com','x','minor',15,'t_4','Self') $q$,\n  'nobody is their own guardian');\n\nSELECT pg_temp.must_reject(\n  $q$ INSERT INTO app_users (user_id,email,password_hash,kind,age,guardian_id,display_name)\n      VALUES ('t_5','young@example.com','x','minor',8,'g_1','Too young') $q$,\n  'an age below 10 is rejected');\n\nINSERT INTO app_users (user_id,email,password_hash,kind,age,guardian_id,display_name)\nVALUES ('t_ok_g','guardian@example.com','x','guardian',44,NULL,'A Guardian');\nINSERT INTO app_users (user_id,email,password_hash,kind,age,guardian_id,display_name)\nVALUES ('t_ok_m','teen@example.com','x','minor',15,'t_ok_g','A Teen');\n\nSELECT pg_temp.must_reject(\n  $q$ INSERT INTO app_users (user_id,email,password_hash,kind,age,guardian_id,display_name)\n      VALUES ('t_6','TEEN@example.com','x','adult',30,NULL,'Duplicate') $q$,\n  'a duplicate email is rejected regardless of case');\n\nSELECT 'ok   — a guardian and a linked minor both insert';\n\nROLLBACK;\n";
